attribute vec3 aO; attribute vec2 aP; attribute float aT, aV, aG, aEl; uniform float uTime; varying vec2 vQ; varying float vU, vK, vG, vEl; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){ if (aV < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float u = uTime - aT, k = eox(clamp(u/.3, 0., 1.)), R = mix(.08, 0.58, k);
      vU = u; vK = aP.y < -.5 ? 1. : 0.; vG = uTime - aG; vEl = aEl;
      if (aP.y < -.5){                                           // orbit line: flat ring quad in the horizontal plane
        float S = .72; vQ = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, 0.95, -position.y*S), 1.); return; }
      float ang = aP.x + aP.y*3.14159 + uTime*.7;                  // two memory crystals, opposite each other
      float g = uTime - aG; vG = g;                                 // time since this shard was gained
      vec3 c = aO + vec3(cos(ang)*R, 0.95 + .25*(1. - k), sin(ang)*R);
      float gs = g >= 0. && g < .25 ? 1. + 2.2*(1. - g/.25) : 1.;     // the quad grows while the gain flash plays
      vec4 mv = viewMatrix*vec4(c, 1.); vec2 q = position.xy; mv.xy += q*vec2(.07, .13)*gs;
      vQ = q*gs; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uCW, uF, uI, uL, uLA, uLB; varying vec2 vQ; varying float vU, vK, vG, vEl; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float pk = vU < .033 ? 2. : 1. + .8*exp(-max(vU - .033, 0.)*10.);
      vec3 o = vec3(0.);
      if (vK > .5){
        // thin orbit line: fine core + narrow soft halo, energy drifting slowly in the shards' direction
        float r = length(vQ), a = atan(vQ.y, vQ.x), R = mix(.08, 0.58, eox(clamp(vU/.3, 0., 1.)));
        float flow = .6 + .4*pow(.5 + .5*sin(a*3. + uTime*1.4), 2.);
        float line = lineCore(r - R, .004)*.55 + exp(-pow((r - R)/.025, 2.))*.1;
        if (vG >= 0. && vG < .32){                                          // II: a pulse of light runs once around the orbit
          float head = vG/.3*6.2832 - 3.14159, da = mod(a - head + 3.14159, 6.2832) - 3.14159;
          float tail = exp(-pow(max(-da, 0.)/.9, 2.))*step(da, .05)*exp(-pow(min(da, 0.)/.9, 2.)), hd = exp(-da*da*60.);
          vec3 pc = mix(uLA, uLB, step(0., sin(a*2.)));                    // mixed pairs: two colours around the ring
          o = pc*(lineCore(r - R, .005)*(tail*1.2 + hd*2.5))*(1. - smoothstep(.26, .32, vG));
          line *= 1. + (tail*1.2 + hd*2.)*(1. - smoothstep(.26, .32, vG));
        }
        o = (vG >= 0. && vG < .32 ? o : vec3(0.)) + (uCW*line*flow + mix(uCW, vec3(1.), .5)*lineCore(r - R, .0025)*.25*flow)*pk;
        o *= smoothstep(.72, .66, r);
      } else {
        float d = abs(vQ.x) + abs(vQ.y)*.55 - .55;                          // elongated diamond (the icon's crystal)
        float edge = lineCore(d, .07), fill = .18*smoothstep(.05, -.1, d), facet = .5*lineCore(vQ.x, .05)*smoothstep(0., -.2, d);
        float halo = exp(-dot(vQ, vQ)*5.)*.12;
        vec3 ec = vEl < .5 ? uF : (vEl < 1.5 ? uI : uL);                   // the element this memory holds
        o = (ec*(edge*.8 + fill + halo) + mix(ec, vec3(1.), .6)*facet*.6)*pk*(.85 + .15*sin(uTime*2. + vQ.y));
        o *= smoothstep(1., .8, length(vQ));                                // reaches zero before the quad edge
        if (vG >= 0. && vG < .25){                                          // gain: 2-frame peak, a short ring of sparks around the new shard
          float t = vG/.25, gs = 1. + 2.2*(1. - t), r = length(vQ*vec2(.07, .13)/.07);
          float R = mix(.6, 2.6, 1. - pow(1. - t, 3.)), a = atan(vQ.y*.13, vQ.x*.07);
          float ring = exp(-pow((r - R)/.12, 2.))*(.5 + .5*pow(abs(sin(a*4.)), 6.))*(1. - t);
          o *= vG < .033 ? 2.6 : 1. + 1.2*(1. - t);
          o += (ec*ring*.8 + mix(ec, vec3(1.), .6)*exp(-r*r*.6)*(1. - t)*.6)*smoothstep(gs*1.1, gs*.9, r*.9);
        }
      }
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }

